import os
import signal

PIDS = [1406, 1601, 1974, 1536, 2644]

for pid in PIDS:
    try:
        os.kill(pid, signal.SIGKILL)
        print(f"killed {pid}")
    except ProcessLookupError:
        print(f"gone   {pid}")
    except PermissionError:
        print(f"denied {pid}")

